function OverseaManagePersonnelFoodPopup:FreshFilterNode()
    ---@type UIAreaFilterMB
    local filterNodeEnv = self:GetFilterNodeEnv()
    if isNull(filterNodeEnv) then return end
    filterNodeEnv:InitSortTypeList(Constants.ScreenType.CatBallFoodShow,true)
    filterNodeEnv:SetCallback( function(sortId)
        self.showFoodVos = self:GetFoodVosBySortId(sortId)
        self:FreshGridView()
    end,Constants.ScreenType.CatBallFoodShow)
end
---查找排序的条件会很慢 涉及的方法比较多 所以做个缓存 解决点击全部卡顿的情况 
function OverseaManagePersonnelFoodPopup:GetFoodVosBySortId(sortId)
    if self.sortData[sortId] then
        return self.sortData[sortId]
    end
    local data = {}
    if checkNumber(sortId) == 888 then
        data = self.allFoodVos
    else
        for i, v in pairs(self.allFoodVos) do
            for k, j in pairs(v.skillArea) do
                if checkNumber(j) == checkNumber(sortId) then
                    table.insert(data,v)
                end
            end
        end
    end

    table.sort(data,function(a,b)
        local aIsUnLock = GameUtils.IsUnlockedSingle(a.unlockType, a.unlockNum, a.unlockId) and 1 or 0
        local bIsUnLock = GameUtils.IsUnlockedSingle(b.unlockType, b.unlockNum, b.unlockId) and 1 or 0
        if aIsUnLock == bIsUnLock then
            local aRate = self:GetFoodRate(a.food)
            local bRate = self:GetFoodRate(b.food)
            if aRate == bRate then
                return a.food > b.food
            else
                return aRate > bRate
            end
        else
            return aIsUnLock > bIsUnLock
        end
    end)
    self.sortData[sortId] = data
    return data
end

function OverseaManagePersonnelFoodPopup:GetFoodRate(id)
    local goodsVo =  GoodsConfMgr:GetInstance():GetGoodsVoById(id)
    if goodsVo then
        return goodsVo.quality
    end
    return 0
end

