    if isNull(self._filterNodeEnv) then
        self._filterNodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, UICommonFilterMBEnvPath)
    end
    return self._filterNodeEnv
end

function OverseaManagePersonnelFoodPopup:GetAllCatFoodData()
    if isNull(self.allVos) then
        self.allVos = CfUtils.GetCf(AutoIds.IdSetting4114, "MaidCoffeeCatBallFoodVo", true )
    end
    return self.allVos
end

function OverseaManagePersonnelFoodPopup:FreshGridView()
    self.count = table.count(self.showFoodVos)
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitGridView(self.count, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, self.count)
        self.ScrollView.ContainerTrans.anchoredPosition3D = Vector3(0,0,0)
        self.ScrollView:VaildAndSetContainerPos()
    end
end

function OverseaManagePersonnelFoodPopup:OnGetItemByIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    if self.count < (index + 1) then
        return nil
    end

    local cell = listView:NewListViewItem(FoodCell)
    if not isNull(cell) then
        local env = CfUtils.GetLuaScr(cell,FoodCellPath)
        if env then
            env:RefreshFoodShow(self.showFoodVos[index + 1])
        end
    end
    return cell
end

function OverseaManagePersonnelFoodPopup:OnBtnCloseClick()
    UIModule.CloseDialog(self.controller)
end
